		"voters":              voterIDs,
		"nonvoters":           nonvoterIDs,
		"quorum_size":         quorum,
		"leader_term":         leader.raft.getCurrentTerm(),
		"other_max_term":      maxOtherTerm,
		"other_states":        otherStates,
		"leader_state_after":  leader.raft.State().String(),
		"verify_error":        verifyErr,
